import{_ as o,C as d,o as r,c as s,aj as a,E as n}from"./framework.js";const m=JSON.parse('{"title":"页面 | Cms / Site | Documentation","description":"管理站点内所有可访问 URL 的 Page 资源：列表维护、路由、代码编辑与在线编辑。页面 HTML 与 Layout 写法见 模板引擎 · Page；脚本 CRUD 见 k.site.pages。","frontmatter":{"title":"页面 | Cms / Site | Documentation","description":"管理站点内所有可访问 URL 的 Page 资源：列表维护、路由、代码编辑与在线编辑。页面 HTML 与 Layout 写法见 模板引擎 · Page；脚本 CRUD 见 k.site.pages。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/site/pages.html"}]]},"headers":[],"relativePath":"zh/cms/site/pages.md","filePath":"cms/site/pages.md","lastUpdated":1780283118000}'),l={name:"zh/cms/site/pages.md"};function i(h,t,g,c,p,b){const e=d("DocImage");return r(),s("div",null,[t[0]||(t[0]=a('<h1 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to &quot;页面&quot;">​</a></h1><blockquote><p>菜单：<strong>页面</strong>（左侧顶栏）<br> 深链：<code>/_Admin/site/pages?SiteId={站点GUID}</code></p></blockquote><p>管理站点内所有可访问 URL 的 <strong>Page</strong> 资源：列表维护、路由、代码编辑与在线编辑。页面 HTML 与 Layout 写法见 <a href="/kb-docs/zh/templateEngine/page/">模板引擎 · Page</a>；脚本 CRUD 见 <a href="/kb-docs/zh/api/site/page.html">k.site.pages</a>。</p><div class="tip custom-block"><p class="custom-block-title">前置</p><p>建议已了解 <a href="./media.html">媒体库</a>（图片引用）与 <a href="./dashboard.html">控制面板</a>。使用 <strong>Layout 页面</strong> 前，须在 <strong>开发 → Layout</strong> 中已有至少一个 Layout。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>进入站点后台，点击左侧顶栏 <strong>页面</strong>。</li><li>地址栏为 <code>/_Admin/site/pages?SiteId=...</code>。</li></ol>',6)),n(e,{src:"/cms/site/pages-list.png",alt:"页面列表",width:"1120"}),t[1]||(t[1]=a('<h2 id="页面列表" tabindex="-1">页面列表 <a class="header-anchor" href="#页面列表" aria-label="Permalink to &quot;页面列表&quot;">​</a></h2><p>默认以<strong>表格</strong>展示站点内全部页面，常用列含义如下：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>页面资源名；带 <strong>主页</strong> 图标的为站点起始页或首页链接</td></tr><tr><td>链接</td><td>是否被其他资源引用</td></tr><tr><td>在线</td><td>页面是否已发布且站点已发布</td></tr><tr><td>引用</td><td>被哪些 Layout / View / 内容等引用</td></tr><tr><td>最后修改</td><td>最近保存时间</td></tr><tr><td>预览</td><td>访问路径，点击可在新窗口预览</td></tr></tbody></table><p>右上角可在 <strong>页面</strong> / <strong>页面树</strong> 两种视图间切换：</p><ul><li><strong>页面</strong>：平铺列表，适合查找、批量删除、复制。</li><li><strong>页面树</strong>：按 DOM 结构展示站点页面层级，支持关键词搜索与高级筛选（标签名、Id、Class 等），适合梳理整站结构。</li></ul><h2 id="工具栏" tabindex="-1">工具栏 <a class="header-anchor" href="#工具栏" aria-label="Permalink to &quot;工具栏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>创建页面</strong></td><td>下拉选择页面类型后进入创建/设置流程</td></tr><tr><td><strong>创建设计页面</strong></td><td>基于已有 Layout 创建可视化设计页（需站点开启页面元素且存在 Layout）</td></tr><tr><td><strong>导入</strong></td><td>从包或外部导入页面</td></tr><tr><td><strong>路由设置</strong></td><td>集中管理多页面路由规则（需 <code>pages</code> 的 router 权限）</td></tr></tbody></table><h2 id="创建页面" tabindex="-1">创建页面 <a class="header-anchor" href="#创建页面" aria-label="Permalink to &quot;创建页面&quot;">​</a></h2><p>点击 <strong>创建页面</strong>，在下拉菜单中选择类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>HTML 页面</strong></td><td>独立 HTML，可不绑 Layout；适合落地页或完整文档结构</td></tr><tr><td><strong>富文本页面</strong></td><td>富文本编辑器维护内容，适合简单图文页</td></tr><tr><td><strong>{Layout 名} 页面</strong></td><td>绑定指定 Layout，Page 内通过 <code>&lt;placeholder&gt;</code> 填充布局占位区</td></tr></tbody></table><p>创建 <strong>HTML 页面</strong> 时先填写 <strong>页面名称</strong> 与 <strong>URL</strong>（路径须唯一；新建时改名称会自动建议 <code>/{名称}</code> 形式的路径）。保存后进入<strong>代码编辑</strong>或<strong>设置</strong>。</p><p>创建 <strong>Layout 页面</strong> 时带上 <code>layoutId</code>，进入该 Layout 对应的页面设置与编辑流程。</p><div class="tip custom-block"><p class="custom-block-title">与模板引擎对应</p><table tabindex="0"><thead><tr><th>后台类型</th><th>模板写法</th></tr></thead><tbody><tr><td>HTML 页面</td><td>完整 <code>&lt;!DOCTYPE html&gt;</code> 或自建结构</td></tr><tr><td>Layout 页面</td><td><code>&lt;layout id=&quot;...&quot;&gt;&lt;placeholder id=&quot;...&quot;&gt;</code></td></tr><tr><td>富文本页面</td><td>由系统生成 HTML，一般不手写占位</td></tr></tbody></table></div><h2 id="列表行操作" tabindex="-1">列表行操作 <a class="header-anchor" href="#列表行操作" aria-label="Permalink to &quot;列表行操作&quot;">​</a></h2><p>选中一行后，右侧通常有三个入口（权限与页面类型不同，图标可能略有差异）：</p><table tabindex="0"><thead><tr><th>入口</th><th>文档</th><th>作用</th></tr></thead><tbody><tr><td><strong>设置</strong></td><td><a href="./pages-setting.html">页面设置</a></td><td>URL、标题、Meta、本页样式/脚本、缓存；左侧为实时预览</td></tr><tr><td><strong>编辑代码</strong> / <strong>设计</strong></td><td><a href="./pages-edit-code.html">编辑代码</a></td><td>改 Page 的 HTML body（Designer 类型为可视化设计器）</td></tr><tr><td><strong>在线编辑</strong></td><td><a href="./pages-inline-edit.html">在线编辑</a></td><td>在预览页上点选改文案、图、链与局部样式</td></tr></tbody></table><p>批量：勾选多行后可 <strong>删除</strong>；选中单行时可 <strong>复制</strong> 页面。</p><div class="tip custom-block"><p class="custom-block-title">三种方式怎么选</p><ul><li><strong>设置</strong> — 路由与 SEO、发布状态、引用哪些 Style/Script，不改正文 HTML。</li><li><strong>编辑代码</strong> — 搭骨架、写 Layout 占位、插 View。</li><li><strong>在线编辑</strong> — 已上线页的可见内容微调。</li></ul></div><h2 id="路由设置" tabindex="-1">路由设置 <a class="header-anchor" href="#路由设置" aria-label="Permalink to &quot;路由设置&quot;">​</a></h2><p>当站点页面较多、或需统一调整 URL 规则时，在列表工具栏打开 <strong>路由设置</strong>，在对话框中批量维护路由（具体字段以界面为准）。</p><h2 id="与开发文档的关系" tabindex="-1">与开发文档的关系 <a class="header-anchor" href="#与开发文档的关系" aria-label="Permalink to &quot;与开发文档的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台操作</th><th>开发文档</th></tr></thead><tbody><tr><td>页面 HTML / Layout 占位</td><td><a href="/kb-docs/zh/templateEngine/page/">Page</a> · <a href="/kb-docs/zh/templateEngine/layout/">Layout</a></td></tr><tr><td>插入可复用块</td><td><a href="/kb-docs/zh/templateEngine/view/">View</a></td></tr><tr><td>脚本创建页面、改 URL</td><td><a href="/kb-docs/zh/api/site/page.html">k.site.pages</a></td></tr><tr><td>当前请求改 title/meta</td><td><a href="/kb-docs/zh/api/page/">k.page</a></td></tr><tr><td>页面内图片</td><td><a href="./media.html">媒体库</a> · <a href="/kb-docs/zh/api/media/">k.media</a></td></tr></tbody></table><h2 id="典型流程-新建可访问的关于页" tabindex="-1">典型流程：新建可访问的关于页 <a class="header-anchor" href="#典型流程-新建可访问的关于页" aria-label="Permalink to &quot;典型流程：新建可访问的关于页&quot;">​</a></h2><ol><li><strong>页面</strong> → <strong>创建页面</strong> → <strong>HTML 页面</strong>。</li><li>填写名称 <code>about</code>、URL <code>/about</code>，保存。</li><li>点击 <a href="./pages-edit-code.html">编辑代码</a>，写入页面结构（或 <code>&lt;layout&gt;</code> 形式，若已用 Layout）。</li><li>在 <a href="./pages-setting.html">页面设置</a> 中确认已发布，点击 <strong>预览</strong> 验证 <code>/about</code>。</li><li>若需脚本动态注册，再参考 <a href="/kb-docs/zh/api/site/page.html">k.site.pages</a>。</li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./dashboard.html">控制面板</a></td><td>「我的资源」中的页面数量</td></tr><tr><td><a href="./media.html">媒体库</a></td><td>页面与内容中的图片</td></tr><tr><td><a href="./../content/contents-folders-list.html">内容列表</a></td><td>内容详情页常配合独立 Page URL</td></tr></tbody></table>',26))])}const f=o(l,[["render",i]]);export{m as __pageData,f as default};
